-- 016 — Reversa Gov: catálogo nacional de municípios (IBGE, 5.571 municípios). Tabela de referência global, sem organization_id.
-- O menu raiz do Gov lista este catálogo; o município só entra no CRM/Kanban do Gov quando o primeiro diagnóstico é gerado.
create table if not exists gov_catalogo_municipios (
  ibge_code char(7) primary key,
  name varchar(240) not null,
  name_search varchar(240) not null,
  state char(2) not null,
  region varchar(20) not null,
  is_capital boolean not null default false,
  latitude numeric(9,4),
  longitude numeric(9,4)
);
create index if not exists gov_catalogo_state_idx on gov_catalogo_municipios (state, name_search);
create index if not exists gov_catalogo_search_idx on gov_catalogo_municipios (name_search);
